from sheet import CycleError, evaluate

cases = [
    ({'A': '=2^3^2'}, 512.0),
    ({'A': '=-2^2'}, -4.0),
    ({'A': '=(-2)^2'}, 4.0),
    ({'A': '=2^-2'}, 0.25),
    ({'A': '=20/5/2'}, 2.0),
    ({'A': '= -( 1 + 2 ) * 3'}, -9.0),
    ({'A': '=B+1', 'B': '=C*2', 'C': '3.5'}, 8.0),
]
for cells, expected in cases:
    actual = evaluate(cells)['A']
    assert actual == expected, (cells, actual, expected)

for cells in ({'A': '=A'}, {'A': '=B', 'B': '=C', 'C': '=A'}):
    try:
        evaluate(cells)
    except CycleError:
        pass
    else:
        raise AssertionError(f'missed cycle: {cells}')

try:
    evaluate({'A': '=1/0'})
except ZeroDivisionError:
    pass
else:
    raise AssertionError('division by zero did not raise')

print('manual edge cases passed')
